/**
 * Baked elevation grids for the contour animations.
 *
 * The prototype fetched nine terrarium tiles per city from a third-party
 * bucket on every mount and decoded them in the browser. That is a runtime
 * dependency on someone else's service for a marketing page, so the grids
 * are baked here instead, the same way the OpenStreetMap and star-catalog
 * data already are.
 *
 * Source: AWS Terrain Tiles, terrarium encoding, zoom 12, a 3x3 tile block
 * cropped to 512x512 and sampled down to a 180 x 180 grid of metres.
 * Regenerate by re-running the bake against the same tile coordinates:
 *   Mt Hood      x 662, 663, 664  y 1466, 1467, 1468  crop 92, 128
 *   Pittsburgh   x 1136, 1137, 1138  y 1543, 1544, 1545  crop 210, 51
 */

export interface Terrain {
  /** Grid is square, this many samples per side. */
  G: number;
  /** Elevation in metres, row-major, length G*G. */
  grid: Int16Array;
  min: number;
  max: number;
  /** Grid coordinates of the highest sample. */
  peak: { x: number; y: number };
}

export type TerrainId = 'hood' | 'pgh';

const GRID_SIZE = 180;

/** Int16 metres, little-endian, base64. */
// prettier-ignore -- one literal per grid; prettier overflows its stack
// trying to reflow these as concatenations.
const ENCODED: Record<TerrainId, string> = {
  hood: '',
  pgh: '',
};

const META: Record<
  TerrainId,
  { min: number; max: number; peak: { x: number; y: number } }
> = {
  hood: { min: 848, max: 3412, peak: { x: 89, y: 81 } },
  pgh: { min: 215, max: 414, peak: { x: 66, y: 8 } },
};

const cache = new Map<TerrainId, Terrain>();

/** Decode a baked grid. Synchronous, so there is no loading state. */
export function terrain(id: TerrainId): Terrain {
  const hit = cache.get(id);
  if (hit) return hit;
  const bin = atob(ENCODED[id]);
  const bytes = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
  const meta = META[id];
  const value: Terrain = {
    G: GRID_SIZE,
    grid: new Int16Array(bytes.buffer),
    min: meta.min,
    max: meta.max,
    peak: meta.peak,
  };
  cache.set(id, value);
  return value;
}
